export const AUDIT_OUTCOMES = [
  "success",
  "denied",
  "failure"
] as const;

export type AuditOutcome = (typeof AUDIT_OUTCOMES)[number];

/**
 * An immutable description of an auditable action.
 *
 * Use metadata for non-secret contextual details such as a lifecycle
 * transition's previous and resulting statuses. Do not store passwords,
 * connection strings, access tokens, or other credentials here.
 *
 * Persistence-specific identifiers and timestamps may be generated by
 * the storage adapter. The adapter must document how it maps this contract
 * to the actual audit_events schema.
 */
export interface AuditEvent {
  readonly action: string;
  readonly actorId: string | null;
  readonly tenantId: string | null;
  readonly resourceType: string;
  readonly resourceId: string | null;
  readonly outcome: AuditOutcome;
  readonly occurredAt?: Date;
  readonly requestId?: string;
  readonly metadata?: Readonly<Record<string, unknown>>;
}
